}

test "phase7_run_multiple_ops" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    const a = 10;
        \\    const b = 20;
        \\    const c = a + b;
        \\    return c + 2;
        \\}
    ;

    const result = compileAndRun(source, allocator) catch |err| {
        std.debug.print("Skip: {}\n", .{err});
        return;
    };

    try std.testing.expectEqual(@as(u8, 32), result.exit_code);
}

// ========== Phase 7 테스트: 제어흐름 (2개) ==========

test "phase7_run_if_true_branch" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    if (1 == 1) {
        \\        return 10;
        \\    }
        \\    return 0;
        \\}
    ;

    const result = compileAndRun(source, allocator) catch |err| {
        std.debug.print("Skip: {}\n", .{err});
        return;
    };

