// 🦎 Phase 9: 크로스 컴파일 및 타겟 지원 테스트
// test/phase9_cross_compile_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Sema = @import("../src/sema.zig").Sema;
const LLVMIRGen = @import("../src/llvm_ir.zig").LLVMIRGen;
const Target = @import("../src/llvm_ir.zig").Target;
const Linker = @import("../src/linker.zig").Linker;

/// 소스 코드 → LLVM IR 생성 (특정 타겟)
fn compileToIR(source: []const u8, target: Target, allocator: std.mem.Allocator) ![]const u8 {
    // Step 1: Tokenize
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(@import("../src/tokenizer.zig").Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    // Step 2: Parse
    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    const ast = try parser.parseProgram();

    // Step 3: AstGen
    var astgen = try AstGen.init(allocator, source);
    defer astgen.deinit();
    try astgen.genProgram(&ast);

    // Step 4: Sema
    var sema = try Sema.init(allocator, &astgen.zir);
    defer sema.deinit();
    try sema.analyzeProgram();

    if (sema.hasErrors()) {
        return error.SemanticErrors;
    }

    // Step 5: LLVMIRGen with target
    var llvm_gen = try LLVMIRGen.initWithTarget(allocator, &sema.air, target);
    defer llvm_gen.deinit();
    return try llvm_gen.generate();
}

// ========== Phase 9 테스트: 타겟 설정 (3개) ==========

test "phase9_target_x86_64" {
    const target = Target.x86_64_linux;
    try std.testing.expectEqual(Target.x86_64_linux, target);
}

test "phase9_target_aarch64" {
    const target = Target.aarch64_linux;
    try std.testing.expectEqual(Target.aarch64_linux, target);
}

test "phase9_target_riscv64" {
    const target = Target.riscv64_linux;
    try std.testing.expectEqual(Target.riscv64_linux, target);
}

// ========== Phase 9 테스트: IR 생성 (3개) ==========

test "phase9_ir_has_correct_triple_x86" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 0;
        \\}
    ;

    const ir_text = try compileToIR(source, .x86_64_linux, allocator);
    defer allocator.free(ir_text);

    // x86_64 triple 확인
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_text, 1, "x86_64-unknown-linux-gnu"));
}

test "phase9_ir_has_correct_triple_arm" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 0;
        \\}
    ;

    const ir_text = try compileToIR(source, .aarch64_linux, allocator);
    defer allocator.free(ir_text);

    // aarch64 triple 확인
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_text, 1, "aarch64-unknown-linux-gnu"));
}

test "phase9_ir_has_correct_datalayout" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 0;
        \\}
    ;

    const ir_x86 = try compileToIR(source, .x86_64_linux, allocator);
    const ir_arm = try compileToIR(source, .aarch64_linux, allocator);
    defer {
        allocator.free(ir_x86);
        allocator.free(ir_arm);
    }

    // x86_64와 aarch64의 data layout이 다른지 확인
    try std.testing.expect(!std.mem.eql(u8, ir_x86, ir_arm));
}

// ========== Phase 9 테스트: 파일 출력 (3개) ==========

test "phase9_write_arm64_ir" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 42;
        \\}
    ;

    const ir_text = try compileToIR(source, .aarch64_linux, allocator);
    defer allocator.free(ir_text);

    // 임시 파일에 저장
    const temp_file = try Linker.generateTempFileName(allocator, "_arm64.ll");
    defer allocator.free(temp_file);

    try Linker.writeIRToFile(ir_text, temp_file);
    defer Linker.deleteFile(temp_file) catch {};

    // 파일이 존재하는지 확인
    try std.testing.expect(Linker.fileExists(temp_file));
}

test "phase9_ir_file_triple_matches" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 0;
        \\}
    ;

    const ir_text = try compileToIR(source, .riscv64_linux, allocator);
    defer allocator.free(ir_text);

    // RISC-V triple 확인
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_text, 1, "riscv64-unknown-linux-gnu"));
}

test "phase9_default_target_x86" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 0;
        \\}
    ;

    // 기본 타겟 (initWithTarget 없이 init() 호출)
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(@import("../src/tokenizer.zig").Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    const ast = try parser.parseProgram();

    var astgen = try AstGen.init(allocator, source);
    defer astgen.deinit();
    try astgen.genProgram(&ast);

    var sema = try Sema.init(allocator, &astgen.zir);
    defer sema.deinit();
    try sema.analyzeProgram();

    // 기본 init() 사용 → x86_64_linux 기본값
    var llvm_gen = try LLVMIRGen.init(allocator, &sema.air);
    defer llvm_gen.deinit();

    const ir_text = try llvm_gen.generate();
    defer allocator.free(ir_text);

    // x86_64 기본 타겟 확인
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_text, 1, "x86_64-unknown-linux-gnu"));
}

// ========== Phase 9 테스트: 크로스 컴파일 (2개) ==========

test "phase9_cross_compile_if_available" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 7;
        \\}
    ;

    const ir_text = try compileToIR(source, .aarch64_linux, allocator);
    defer allocator.free(ir_text);

    // IR에 ARM64 triple이 포함되어 있는지 확인
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_text, 1, "aarch64-unknown-linux-gnu"));

    var linker = try Linker.init(allocator);
    defer linker.deinit();

    // clang이 있으면 크로스 컴파일 시도 (선택적)
    if (linker.llvm_path != null) {
        const temp_ll = try Linker.generateTempFileName(allocator, "_test.ll");
        defer allocator.free(temp_ll);
        const temp_bin = try Linker.generateTempFileName(allocator, "_test_arm");
        defer allocator.free(temp_bin);

        try Linker.writeIRToFile(ir_text, temp_ll);
        defer Linker.deleteFile(temp_ll) catch {};

        // clang --target aarch64-unknown-linux-gnu 사용 (구현 미포함, 테스트만 검증)
        _ = temp_bin;
    }
}

test "phase9_cross_target_binary_exists" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 0;
        \\}
    ;

    var linker = try Linker.init(allocator);
    defer linker.deinit();

    if (linker.llvm_path != null) {
        const ir_text = try compileToIR(source, .x86_64_linux, allocator);
        defer allocator.free(ir_text);

        const temp_ll = try Linker.generateTempFileName(allocator, "_check.ll");
        defer allocator.free(temp_ll);

        try Linker.writeIRToFile(ir_text, temp_ll);
        defer Linker.deleteFile(temp_ll) catch {};

        // IR 파일이 생성되었는지 확인
        try std.testing.expect(Linker.fileExists(temp_ll));
    }
}

// ========== Phase 9 통합 테스트 (2개) ==========

test "phase9_full_pipeline_arm64" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn add(a: i32, b: i32) i32 {
        \\    return a + b;
        \\}
        \\fn main() i32 {
        \\    return add(20, 22);
        \\}
    ;

    const ir_text = try compileToIR(source, .aarch64_linux, allocator);
    defer allocator.free(ir_text);

    // ARM64 triple 및 data layout 확인
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_text, 1, "aarch64-unknown-linux-gnu"));
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_text, 1, "target datalayout"));
}

test "phase9_all_targets_ir_generation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() i32 {
        \\    return 0;
        \\}
    ;

    const targets = [_]Target{
        .x86_64_linux,
        .aarch64_linux,
        .riscv64_linux,
        .x86_64_macos,
        .aarch64_macos,
    };

    for (targets) |target| {
        const ir_text = try compileToIR(source, target, allocator);
        defer allocator.free(ir_text);

        // 모든 타겟에 대해 IR이 생성되는지 확인
        try std.testing.expect(ir_text.len > 0);

        // target triple이 포함되어 있는지 확인
        try std.testing.expect(std.mem.containsAtLeast(u8, ir_text, 1, "target triple"));
    }
}

